class Solution:
    def addRungs(self, rungs: List[int], dist: int) -> int:
        def ceil_divide(a, b):
            return (a+(b-1))//b

        result = prev = 0
        for curr in rungs:
            result += ceil_divide(curr-prev, dist)-1
            prev = curr
        return result

